import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential
from azure.core.exceptions import AzureError, HttpResponseError

AZURE_AI_DOCUMENT_INTELLIGENCE_ENDPOINT = os.getenv("AZURE_AI_DOCUMENT_INTELLIGENCE_ENDPOINT")
AZURE_AI_DOCUMENT_INTELLIGENCE_API_KEY = os.getenv("AZURE_AI_DOCUMENT_INTELLIGENCE_API_KEY")

def validate_structured_extraction(file_path, required_fields, min_confidence=0.85):
    if not AZURE_AI_DOCUMENT_INTELLIGENCE_ENDPOINT or not AZURE_AI_DOCUMENT_INTELLIGENCE_API_KEY:
        raise ValueError(
            "Environment variables AZURE_AI_DOCUMENT_INTELLIGENCE_ENDPOINT and "
            "AZURE_AI_DOCUMENT_INTELLIGENCE_API_KEY must be configured."
        )

    client = DocumentAnalysisClient(
        endpoint=AZURE_AI_DOCUMENT_INTELLIGENCE_ENDPOINT,
        credential=AzureKeyCredential(AZURE_AI_DOCUMENT_INTELLIGENCE_API_KEY)
    )

    try:
        with open(file_path, "rb") as document_file:
            poller = client.begin_analyze_document(
                model_id="prebuilt-invoice", 
                document=document_file
            )
            result = poller.result()
    except HttpResponseError as e:
        return {"is_valid": False, "error": f"Azure API request failed: {e.message}"}
    except AzureError as e:
        return {"is_valid": False, "error": f"Failed to process document: {str(e)}"}
    except Exception as e:
        return {"is_valid": False, "error": f"Unexpected error: {str(e)}"}

    if not result.documents:
        return {"is_valid": False, "error": "No documents were detected in the provided file."}

    doc_fields = result.documents[0].fields
    validation_report = {
        "is_valid": True,
        "extracted_values": {},
        "missing_fields": [],
        "low_confidence_fields": []
    }

    for field_name in required_fields:
        field_data = doc_fields.get(field_name)

        if field_data is None:
            validation_report["is_valid"] = False
            validation_report["missing_fields"].append(field_name)
        else:
            confidence = field_data.confidence if field_data.confidence is not None else 0.0
            if confidence < min_confidence:
                validation_report["is_valid"] = False
                validation_report["low_confidence_fields"].append({
                    "field": field_name,
                    "confidence": confidence
                })
            else:
                value = field_data.value
                if isinstance(value, list):
                    value = [item.value if hasattr(item, 'value') else item for item in value]
                validation_report["extracted_values"][field_name] = value

    return validation_report
